import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom'; // පිටු මාරු කරන්න

const Login = () => {
    const [username, setUsername] = useState('');
    const [password, setPassword] = useState('');
    const [error, setError] = useState('');
    const navigate = useNavigate();

    const handleLogin = (e) => {
        e.preventDefault();
        
        // Node.js Backend එකට ඩේටා යැවීම
        fetch('http://localhost:8081/login', { // ඔයාගේ backend port එක (8081 හෝ 3000) දෙන්න
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify({ username, password }),
        })
        .then(response => response.json())
        .then(data => {
            if (data.success) {
                // ලොග් වුණාම ළමයාගේ විස්තර LocalStorage එකේ සේව් කරනවා
                localStorage.setItem('loggedInStudent', JSON.stringify(data.student));
                
                // Dashboard එකට යවනවා
                navigate('/dashboard'); 
            } else {
                setError(data.message); // Error එකක් ආවොත් පෙන්වනවා
            }
        })
        .catch(err => console.error(err));
    };

    return (
        <div style={{ textAlign: 'center', marginTop: '100px' }}>
            <h2>Welcome to Aura Pen</h2>
            {error && <p style={{ color: 'red' }}>{error}</p>}
            
            <form onSubmit={handleLogin}>
                <div>
                    <input 
                        type="text" 
                        placeholder="Student ID (e.g. AP/G9/001)" 
                        value={username}
                        onChange={(e) => setUsername(e.target.value)}
                        style={{ padding: '10px', marginBottom: '10px' }}
                    />
                </div>
                <div>
                    <input 
                        type="password" 
                        placeholder="Password" 
                        value={password}
                        onChange={(e) => setPassword(e.target.value)}
                        style={{ padding: '10px', marginBottom: '10px' }}
                    />
                </div>
                <button type="submit" style={{ padding: '10px 20px', backgroundColor: 'green', color: 'white' }}>
                    Login In...
                </button>
            </form>
        </div>
    );
};

export default Login;
